function main(): void {
  try { Buffer.from(5 as any); } catch (e: any) { console.log(e.code, e.name); }
  try { Buffer.from({} as any); } catch (e: any) { console.log(e.code, e.name); }
  try { Buffer.alloc(-1); } catch (e: any) { console.log(e.code, e.name, e.message); }
  console.log(Buffer.alloc(2).length, Buffer.from("hi").length);
}
